/** 从抖音推荐的歌里挑一首配这条图文；挑不出来就不配，不影响发布。 */
async chooseMusic(text, songs) {
	const list = (Array.isArray(songs) ? songs : []).map((s) => String(s ?? '').trim()).filter(Boolean).slice(0, 10);
	if (!list.length) {
		this.note('post', { title: this.label, reason: '音乐面板一首推荐歌都没抓到（页面可能改版了），这条没 BGM' });
		return '';
	}
	// 列表里常混着「@某某创作的原声」「自带流量的音乐」这类不是歌的条目，能不用就不用
	const junk = /(创作的原声|自带流量|纯音乐|伴奏|BGM)/i;
	const usable = list.filter((s) => !junk.test(s));
	try {
		const raw = String((await this.callLlm(`给这条抖音图文配背景音乐。从下面这些抖音推荐歌里挑一首最适合的（歌名原样照抄），不适合就回空串。\n\n图文正文：\n${text}\n\n推荐歌：\n${list.map((s) => `- ${s}`).join('\n')}\n\n只输出歌名，不要别的。`)) ?? '').trim();
		const picked = pickRecommendedSong(raw, list);
		if (picked) this.note('post', { title: this.label, reason: `配了首《${picked}》` });
		if (picked) return picked;
		// 模型没挑（或挑的名字对不上）→ 退一步用推荐里第一首正经歌，不留空白
		const fb = usable[0] ?? '';
		if (fb) this.note('post', { title: this.label, reason: `模型没挑出来，兜底用了《${fb}》` });
		return fb;
	} catch { return usable[0] ?? ''; }
}

